mapper.select:
SELECT p.*, v.patient_id, pt.real_name AS patient_name, pt.phone AS patient_phone, d.real_name AS doctor_name FROM prescription p JOIN medical_visit v ON v.id = p.visit_id JOIN patient pt ON pt.id = v.patient_id JOIN doctor d ON d.id = p.doctor_id WHERE p.status IN (2, 3)
AND p.status = #{status}
AND p.payment_status = #{paymentStatus}
ORDER BY p.created_at DESC

mapper.update:
UPDATE medicine
   SET stock_quantity = stock_quantity - #{quantity}
 WHERE id = #{medicineId}
   AND stock_quantity >= #{quantity}

UPDATE prescription
   SET status = 3
 WHERE id = #{id}
